export const SKIN_TONES: readonly SkinTone[] = ['1', '2', '3', '4', '5', '6'];

export const withSkinTone = (baseChar: string, skinTone: SkinTone): string => {
  if (!supportsSkinTone(baseChar)) return baseChar;
  return `${baseChar}\u{1F3FB}\u{1F3FC}\u{1F3FD}\u{1F3FE}\u{1F3FF}`.slice(0, baseChar.length + 1);
};

export const supportsSkinTone = (emoji: string): boolean => {
  if (!emoji) return false;
  if (emoji.includes('‍') && emoji.includes('🫁')) return false;
  if (emoji.includes('‍') && baseChar(emoji)) return true;
  return false;
};

export const baseChar = (emoji: string): string | null => {
  for (const c of emoji) {
    if (c >= '\u{1F3FB}' && c <= '\u{1F3FF}') continue;
    if (c === '\u200D') continue;
    if (c === '\uFE0F') continue;
    if (c === '\u200C') continue;
    if (c === '\u200D') continue;
    return c;
  }
  return null;
};

export const search = (query: string): readonly EmojiEntry[] => {
  if (!query) return EMOJI_DATA;
  const q = query.toLowerCase();
  return EMOJI_DATA.filter(
    (entry) =>
      entry.name.toLowerCase().includes(q) ||
      entry.keywords.some((keyword) => keyword.toLowerCase().includes(q)) ||
      entry.char.includes(q),
  );
};

/** Search the unicode catalogue, capped so the virtual list never gets a wall. */
export const searchUnicodeEmoji = (query: string, limit = 240): readonly EmojiEntry[] =>
  search(query).slice(0, Math.max(1, limit));

export const realmEmojiKeyFor = (realmKey?: string): string | null => {
  if (!realmKey) return null;
  const sanitized = realmKey.replace(/[^a-zA-Z0-9\-]/g, '');
  if (!sanitized) return null;
  const found = EMOJI_DATA.find((entry) => entry.name.toLowerCase().includes(sanitized.toLowerCase()));
  return found ? found.char : null;
};

export const UNICODE_EMOJI: readonly string[] = EMOJI_DATA.map(
  (entry) => entry.char,
);

export const EMOJI_BY_NAME: Record<string, readonly EmojiEntry[]> = EMOJI_DATA.reduce(
  (acc, entry) => {
    const key = entry.name.toLowerCase();
    acc[key] = acc[key] ?? [];
    acc[key]!.push(entry);
    return acc;
  },
  {} as Record<string, readonly EmojiEntry[]>,
);

export const categoriesForEmoji = (emoji: string): readonly EmojiCategory[] => {
  return EMOJI_DATA
    .filter((entry) => entry.char === emoji)
    .map((entry) => entry.category);
};

export const emojiCategory = (emoji: string): EmojiCategory | undefined => {
  const entry = EMOJI_DATA.find((e) => e.char === emoji);
  return entry?.category;
};

export const EMOJI_COUNT = EMOJI_DATA.length;

export const TOTAL_CATEGORIES = CATEGORIES.length;

export const EMOJI_CHARS = EMOJI_DATA.map((entry) => entry.char);
